"use server";

import { prisma } from "src/lib/prisma"; 
import { revalidatePath } from "next/cache";

// EKSİK OLAN FONKSİYON BURASIYDI:
export async function createScrumTask(title: string, status: string, userId: string = "test-user") {
  try {
    await prisma.task.create({
      data: {
        title: title,
        status: status as any, // Enum uyumu için
        userId: userId,        // Şemanızda User zorunlu olduğu için bu şart
      },
    });
    revalidatePath("/scrumboard");
  } catch (error) {
    console.error("Task oluşturma hatası:", error);
    throw new Error("Görev oluşturulamadı.");
  }
}

export async function updateTaskStatus(taskId: string, newStatus: string) {
  try {
    await prisma.task.update({
      where: { id: taskId },
      data: { status: newStatus as any },
    });
    revalidatePath("/scrumboard");
  } catch (error) {
    console.error("Güncelleme hatası:", error);
  }
}

export async function deleteScrumTask(taskId: string) {
  try {
    await prisma.task.delete({ where: { id: taskId } });
    revalidatePath("/scrumboard");
  } catch (error) {
    console.error("Silme hatası:", error);
  }
}